using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A binary search given a list out of order, in Python, Java, C#, JavaScript, TypeScript, Go, C, C++, Rust, Ruby, PHP, Lua,
/// Perl, Dart, PowerShell, Scala, Fortran, F# and OCaml: each language's own search given marks written 5, 1, 4, 9, and the
/// library's search - bisect, Arrays.binarySearch, Array.BinarySearch, std::binary_search, sort.SearchInts, binary_search,
/// bsearch, search, [Array]::BinarySearch - given the same. The change writes the marks in order. Left alone: the marks
/// written in order, the marks sorted before the search in each language, and sorts that halve - binary insertion sort,
/// quicksort with a middle pivot, merge sort - given lists out of order.
/// </summary>
public class SortedSearchTests
{
    private static SourceFile Source(string fileName, string code) =>
        new() { Path = Path.Combine(Path.GetTempPath(), fileName), Lines = code.Replace("\r\n", "\n").Split('\n') };

    private static IReadOnlyList<LogicFinding> Scanned(string fileName, string code) =>
        LogicPatterns.Scan(Source(fileName, code))
            .Where(finding => finding.PatternId.EndsWith("-search-unsorted", StringComparison.Ordinal))
            .ToList();

