        { "search.f90", "program main\n  implicit none\n  integer :: marks(4) = [1, 4, 5, 9]\n  print *, contains(marks, 5)\ncontains\n  logical function contains(items, wanted)\n    integer, intent(in) :: items(:), wanted\n    integer :: low, high, mid\n    low = 1\n    high = size(items)\n    contains = .false.\n    do while (low <= high)\n      mid = (low + high) / 2\n      if (items(mid) == wanted) then\n        contains = .true.\n        return\n      end if\n      if (items(mid) < wanted) then\n        low = mid + 1\n      else\n        high = mid - 1\n      end if\n    end do\n  end function contains\nend program main\n" },
