        { "Search.java", "public class Search {\n    static boolean contains(int[] items, int wanted) {\n        int low = 0;\n        int high = items.length - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            if (items[mid] == wanted) {\n                return true;\n            }\n            if (items[mid] < wanted) {\n                low = mid + 1;\n            } else {\n                high = mid - 1;\n            }\n        }\n        return false;\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {1, 4, 5, 9};\n        System.out.println(contains(marks, 5));\n    }\n}\n" },
        { "search.js", "function contains(items, wanted) {\n  let low = 0;\n  let high = items.length - 1;\n  while (low <= high) {\n    const mid = Math.floor((low + high) / 2);\n    if (items[mid] === wanted) {\n      return true;\n    }\n    if (items[mid] < wanted) {\n      low = mid + 1;\n    } else {\n      high = mid - 1;\n    }\n  }\n  return false;\n}\n\nconst marks = [1, 4, 5, 9];\nconsole.log(contains(marks, 5));\n" },
