        { "search.ml", "let contains items wanted =\n  let low = ref 0 in\n  let high = ref (Array.length items - 1) in\n  let found = ref false in\n  while not !found && !low <= !high do\n    let mid = (!low + !high) / 2 in\n    if items.(mid) = wanted then found := true\n    else if items.(mid) < wanted then low := mid + 1\n    else high := mid - 1\n  done;\n  !found\n\nlet marks = [| 1; 4; 5; 9 |]\nlet () = Printf.printf \"%b\\n\" (contains marks 5)\n" },
        { "search.php", "<?php\nfunction contains(array $items, int $wanted): bool\n{\n    $low = 0;\n    $high = count($items) - 1;\n    while ($low <= $high) {\n        $mid = intdiv($low + $high, 2);\n        if ($items[$mid] === $wanted) {\n            return true;\n        }\n        if ($items[$mid] < $wanted) {\n            $low = $mid + 1;\n        } else {\n            $high = $mid - 1;\n        }\n    }\n    return false;\n}\n\n$marks = [1, 4, 5, 9];\nvar_dump(contains($marks, 5));\n" },
