        { "search.py", "def contains(items, wanted):\n    low = 0\n    high = len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == wanted:\n            return True\n        if items[mid] < wanted:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return False\n\n\nmarks = [1, 4, 5, 9]\nprint(contains(marks, 5))\n" },
