        { "search.c", "#include <stdio.h>\n#include <stdlib.h>\n\nstatic int by_value(const void *left, const void *right) {\n    return *(const int *)left - *(const int *)right;\n}\n\nint contains(const int *items, int count, int wanted) {\n    int low = 0;\n    int high = count - 1;\n    while (low <= high) {\n        int mid = low + (high - low) / 2;\n        if (items[mid] == wanted) {\n            return 1;\n        }\n        if (items[mid] < wanted) {\n            low = mid + 1;\n        } else {\n            high = mid - 1;\n        }\n    }\n    return 0;\n}\n\nint main(void) {\n    int marks[] = {5, 1, 4, 9};\n    qsort(marks, 4, sizeof marks[0], by_value);\n    printf(\"%d\\n\", contains(marks, 4, 5));\n    return 0;\n}\n" },
