        { "search.ts", "function contains(items: number[], wanted: number): boolean {\n  let low = 0;\n  let high = items.length - 1;\n  while (low <= high) {\n    const mid = Math.floor((low + high) / 2);\n    if (items[mid] === wanted) {\n      return true;\n    }\n    if (items[mid] < wanted) {\n      low = mid + 1;\n    } else {\n      high = mid - 1;\n    }\n  }\n  return false;\n}\n\nconst marks: number[] = [5, 1, 4, 9];\nmarks.sort((first, second) => first - second);\nconsole.log(contains(marks, 5));\n" },
        { "Sorts.java", "import java.util.Arrays;\n\npublic class Sorts {\n    static int[] binaryInsertionSort(int[] items) {\n        for (int index = 1; index < items.length; index++) {\n            int key = items[index];\n            int low = 0;\n            int high = index - 1;\n            while (low <= high) {\n                int mid = low + (high - low) / 2;\n                if (items[mid] > key) {\n                    high = mid - 1;\n                } else {\n                    low = mid + 1;\n                }\n            }\n            for (int move = index; move > low; move--) {\n                items[move] = items[move - 1];\n            }\n            items[low] = key;\n        }\n        return items;\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {5, 1, 4, 9};\n        System.out.println(Arrays.toString(binaryInsertionSort(marks)));\n    }\n}\n" },
        { "sorts.js", "function binaryInsertionSort(items) {\n  for (let index = 1; index < items.length; index++) {\n    const key = items[index];\n    let low = 0;\n    let high = index - 1;\n    while (low <= high) {\n      const mid = Math.floor((low + high) / 2);\n      if (items[mid] > key) {\n        high = mid - 1;\n      } else {\n        low = mid + 1;\n      }\n    }\n    items.splice(index, 1);\n    items.splice(low, 0, key);\n  }\n  return items;\n}\n\nconst marks = [5, 1, 4, 9];\nconsole.log(binaryInsertionSort(marks));\n" },
        { "sorts.py", "def binary_insertion_sort(items):\n    for index in range(1, len(items)):\n        key = items[index]\n        low = 0\n        high = index - 1\n        while low <= high:\n            mid = (low + high) // 2\n            if items[mid] > key:\n                high = mid - 1\n            else:\n                low = mid + 1\n        items[low + 1:index + 1] = items[low:index]\n        items[low] = key\n    return items\n\n\ndef quicksort(items, low, high):\n    if low >= high:\n        return items\n    mid = (low + high) // 2\n    pivot = items[mid]\n    left = low\n    right = high\n    while left <= right:\n        while items[left] < pivot:\n            left += 1\n        while items[right] > pivot:\n            right -= 1\n        if left <= right:\n            items[left], items[right] = items[right], items[left]\n            left += 1\n            right -= 1\n    quicksort(items, low, right)\n    quicksort(items, left, high)\n    return items\n\n\ndef merge_sort(items):\n    if len(items) <= 1:\n        return items\n    mid = len(items) // 2\n    return merged(merge_sort(items[:mid]), merge_sort(items[mid:]))\n\n\ndef merged(left, right):\n    result = []\n    while left and right:\n        result.append(left.pop(0) if left[0] <= right[0] else right.pop(0))\n    return result + left + right\n\n\nprint(binary_insertion_sort([5, 1, 4, 9]), quicksort([5, 1, 4, 9], 0, 3), merge_sort([5, 1, 4, 9]))\n" },
