    [Theory]
    [MemberData(nameof(Found))]
    public void ASearchGivenAListOutOfOrderIsFound(string fileName, string code, string said)
    {
        Assert.Equal([said], Scanned(fileName, code).Select(finding => $"{finding.Line}|{finding.PatternId}|{finding.Message}"));
    }

    [Theory]
    [MemberData(nameof(Changed))]
    public void TheChangeWritesTheListInOrder(string fileName, string code, string changed)
    {
        var finding = Assert.Single(Scanned(fileName, code));

        Assert.NotNull(finding.Fix);
        Assert.Equal(changed, string.Join("\n", finding.Fix.ApplyTo(Source(fileName, code)) ?? []));
    }

    [Theory]
    [MemberData(nameof(NearMisses))]
    public void AListInOrderOrASortThatHalvesIsLeftAlone(string fileName, string code)
    {
        Assert.Empty(Scanned(fileName, code));
    }
}
